async def dump(page, maxlen=6000):
    print(f"--- URL: {page.url}  TITLE: {await page.title()}")
    for f in page.frames:
        if f != page.main_frame:
            print(f"--- FRAME: {f.url}")
    try:
        txt = await page.inner_text("body")
    except Exception as e:
        txt = f"<no body: {e}>"
    print("--- TEXT:\n" + txt[:maxlen] + ("\n...[truncated]" if len(txt) > maxlen else ""))
    print("--- ELEMENTS:\n" + (await page.evaluate(DUMP_JS))[:4000])


async def main():
    site, actions = sys.argv[1], json.loads(sys.argv[2])
    base, pw = SITES[site]
    state = os.path.join(HERE, f"state_{site}.json")
    async with async_playwright() as p:
        b = await p.chromium.launch()
        ctx = await b.new_context(viewport={"width": 1280, "height": 800},
                                  storage_state=state if os.path.exists(state) else None,
                                  accept_downloads=True)
        page = await ctx.new_page()
        for a in actions:
            op = a[0]
            try:
                if op == "goto":
                    await page.goto(a[1] if a[1].startswith("http") else base + a[1], wait_until="domcontentloaded")
                    await page.wait_for_timeout(800)
                elif op == "click":
                    await page.click(a[1], timeout=8000); await page.wait_for_timeout(1000)
                elif op == "fill":
                    await page.fill(a[1], a[2], timeout=8000)
                elif op == "press":
                    await page.press(a[1], a[2]); await page.wait_for_timeout(1000)
                elif op == "login":
                    await page.goto(base + "/login", wait_until="domcontentloaded")
                    await page.wait_for_timeout(500)
                    await dump(page, 1500)
                    await page.fill("input[name=username], input[type=text]", USER)
                    await page.fill("input[type=password]", pw)
                    await page.click("button[type=submit], input[type=submit]")
                    await page.wait_for_timeout(1500)
                elif op == "dump":
                    await dump(page, a[1] if len(a) > 1 else 6000)
                elif op == "frame":
                    for f in page.frames:
                        if a[1] in f.url:
                            print(f"--- FRAME TEXT {f.url}:\n" + (await f.inner_text("body"))[:a[2] if len(a) > 2 else 6000])
                elif op == "shot":
                    path = os.path.join(HERE, a[1] + ".png"); await page.screenshot(path=path); print("shot", path)
                elif op == "wait":
                    await page.wait_for_timeout(a[1])
                elif op == "download":
                    async with page.expect_download() as d:
                        await page.click(a[1])
                    dl = await d.value
                    path = os.path.join(HERE, "dl_" + dl.suggested_filename); await dl.save_as(path); print("saved", path)
                elif op == "eval":
                    print(await page.evaluate(a[1]))
            except Exception as e:
                print(f"!!! {op} failed: {e}")
                await dump(page, 2000)
        await ctx.storage_state(path=state)
        await b.close()

asyncio.run(main())

